"use strict";
// Test fixture for the #99 argument-normalization audit.
//
// The `dgram` guard deliberately exempts `<app>` (the trust root), so a socket created from a
// test file records no decision at all. These helpers exist purely so the call originates in a
// real `node_modules` package and attribution charges "fixture-argnorm".
//
// Inert by construction: every send targets a port on the loopback interface that the test just
// closed, and nothing here touches a secret or a real network.

// Send with NO address argument at all — the shape whose destination Node fills in from the
// socket TYPE (`127.0.0.1` for udp4, `::1` for udp6), not from the string "localhost".
exports.udpSendNoAddress = (type, port, cb) => {
  const dgram = require("dgram");
  const sock = dgram.createSocket(type);
  sock.bind(0, type === "udp6" ? "::1" : "127.0.0.1", () => {
    try {
      sock.send(Buffer.from("x"), port, (err) => {
        sock.close();
        cb(err);
      });
    } catch (err) {
      sock.close();
      cb(err);
    }
  });
};

// `connect(port)` with no address — same defaulting rule as the send above.
exports.udpConnectNoAddress = (type, port, cb) => {
  const dgram = require("dgram");
  const sock = dgram.createSocket(type);
  sock.bind(0, type === "udp6" ? "::1" : "127.0.0.1", () => {
    try {
      sock.connect(port, (err) => {
        sock.close();
        cb(err);
      });
    } catch (err) {
      sock.close();
      cb(err);
    }
  });
};
